// A grow-only set CRDT: merging two replicas is always
// just a union, which is commutative and conflict-free by construction
Set<String> replicaA = Set.of("item-X");
Set<String> replicaB = Set.of("item-Y");
Set<String> merged = union(replicaA, replicaB); // { item-X, item-Y }
// No matter which order replicas merge in, the result is identical

